import{_ as o,o as a,c as t,a2 as l}from"./chunks/framework.D5wUhsuj.js";const b=JSON.parse('{"title":"能力边界与已知限制","description":"","frontmatter":{},"headers":[],"relativePath":"guide/limitations.md","filePath":"guide/limitations.md","lastUpdated":1784618056000}'),d={name:"guide/limitations.md"};function i(r,e,c,n,s,h){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="能力边界与已知限制" tabindex="-1">能力边界与已知限制 <a class="header-anchor" href="#能力边界与已知限制" aria-label="Permalink to &quot;能力边界与已知限制&quot;">​</a></h1><p>本章集中说明 Tellux 当前版本的能力边界和已知限制，便于在选型和排查时快速判断&quot;能不能做、为什么没生效&quot;。其中部分限制源自底层依赖（Three.js、3d-tiles-renderer、Takram 生态），部分是 Tellux 封装层的现状。</p><h2 id="渲染后端" tabindex="-1">渲染后端 <a class="header-anchor" href="#渲染后端" aria-label="Permalink to &quot;渲染后端&quot;">​</a></h2><h3 id="webgl-默认" tabindex="-1">WebGL（默认） <a class="header-anchor" href="#webgl-默认" aria-label="Permalink to &quot;WebGL（默认）&quot;">​</a></h3><p>完整支持 Tellux 的所有视觉能力：大气天空、空气透视、体积云、星空、后处理（SMAA、镜头光晕、抖动）、瓦片 LOD 淡入淡出。</p><h3 id="webgpu-实验性" tabindex="-1">WebGPU（实验性） <a class="header-anchor" href="#webgpu-实验性" aria-label="Permalink to &quot;WebGPU（实验性）&quot;">​</a></h3><p>WebGPU 是实验能力，以下能力在 WebGPU 模式下<strong>不渲染或不支持</strong>：</p><table tabindex="0"><thead><tr><th>能力</th><th>WebGPU 模式下的状态</th></tr></thead><tbody><tr><td>体积云</td><td>不渲染（应设 <code>clouds.show: false</code>）</td></tr><tr><td>星空</td><td>不渲染</td></tr><tr><td>后处理（SMAA / 镜头光晕 / 抖动）</td><td>不渲染，调整开关无视觉效果</td></tr><tr><td>瓦片 LOD 淡入淡出</td><td>不可用，瓦片为直接切换（pop）</td></tr><tr><td>大气散射调试参数</td><td>部分参数不映射，<code>light-source</code> 光照模式支持更完整</td></tr></tbody></table><ul><li>WebGPU 模式<strong>不会在不支持的环境上自动回退 WebGL</strong>：不支持时 <code>renderer.init()</code> 会 reject，<code>Viewer.create(...)</code> 抛错。应用层需自行检测，或设置 <code>renderer.forceWebGL: true</code> 走 WebGL2 fallback backend。</li><li>WebGPU renderer 需异步初始化，推荐用 <code>Viewer.create(...)</code>；用 <code>new Viewer(...)</code> 时先 <code>await viewer.ready</code>。</li></ul><h2 id="数据与图层" tabindex="-1">数据与图层 <a class="header-anchor" href="#数据与图层" aria-label="Permalink to &quot;数据与图层&quot;">​</a></h2><h3 id="地形" tabindex="-1">地形 <a class="header-anchor" href="#地形" aria-label="Permalink to &quot;地形&quot;">​</a></h3><ul><li>仅支持 <strong>Cesium quantized-mesh</strong> 格式（自托管 URL 或 Cesium Ion）。不支持 GeoTIFF、高度图等其它地形格式。</li><li>地形裙边、法线生成等渲染参数通过 <code>terrain.tileLoading</code> / <code>TerrainRenderOptions</code> 配置。</li></ul><h3 id="影像图层" tabindex="-1">影像图层 <a class="header-anchor" href="#影像图层" aria-label="Permalink to &quot;影像图层&quot;">​</a></h3><ul><li>栅格影像支持 XYZ、WMS、WMTS、Cesium Ion 四种栅格源；矢量图层支持 GeoJSON 和 MVT。</li><li>GeoJSON / MVT 图层是<strong>把矢量内容栅格化成纹理</strong>贴到地表，不是矢量几何直接渲染。样式以像素为单位，受 <code>resolution</code> 影响；极度放大时会出现纹理模糊。</li><li>图层透明度 <code>opacity</code> 作用于整层；<code>color</code> 乘色作用于整层色调。</li></ul><h3 id="_3d-tiles" tabindex="-1">3D Tiles <a class="header-anchor" href="#_3d-tiles" aria-label="Permalink to &quot;3D Tiles&quot;">​</a></h3><ul><li>3D Tiles 作为<strong>独立场景数据</strong>加载，不参与影像 overlay 管线（不能像影像那样贴到地形表面）。</li><li>支持 <code>tileset.json</code>（URL）和 Cesium Ion 两种加载方式；支持 glTF / GLB / B3DM 等常见瓦片，依赖 Draco 时需配置 <code>dracoDecoderPath</code>。</li><li>摄影测量瓦片的法线可能缺失，影响后处理光照，可用 <code>creasedNormals: true</code> 重新生成折痕法线。</li></ul><h2 id="交互与采样" tabindex="-1">交互与采样 <a class="header-anchor" href="#交互与采样" aria-label="Permalink to &quot;交互与采样&quot;">​</a></h2><h3 id="拾取" tabindex="-1">拾取 <a class="header-anchor" href="#拾取" aria-label="Permalink to &quot;拾取&quot;">​</a></h3><ul><li>拾取类方法（<code>pickCartographic</code>、<code>pick</code> / <code>pickAll</code>、事件的 <code>cartographic</code> / <code>pick</code> / <code>picks</code>）<strong>只使用当前已加载到场景中的内容</strong>，不会为视角外的区域额外请求瓦片。</li><li><code>pickCartographic</code> 在未命中 3D Tiles 时回退到 WGS84 椭球表面；对象拾取中的 <code>tilesFeature</code> 不回退椭球，只查已加载 3D Tiles；<code>entity</code> 层只查当前 Viewer 中已添加且可见的实体。</li></ul><h3 id="高度采样" tabindex="-1">高度采样 <a class="header-anchor" href="#高度采样" aria-label="Permalink to &quot;高度采样&quot;">​</a></h3><ul><li><code>sampleHeight</code> 是同步、即时的，<strong>不请求视角外瓦片</strong>，适合当前视图内的每帧贴地查询；视角外或未加载区域返回 <code>undefined</code>。</li><li><code>sampleHeightMostDetailed</code> 会主动加载所需层级瓦片： <ul><li>3D Tiles / 混合模式下临时添加的局部加载区域，采样完成后<strong>保留在主场景缓存</strong>中（升温），后续靠近时可复用，但也会占用缓存。</li><li>当 <code>useDefaultRenderLoop</code> 为 <code>false</code> 时，<strong>必须由调用方继续调用 <code>render()</code></strong> 推进采样，否则任务一直等待，最终超时返回 <code>undefined</code>。</li></ul></li></ul><h2 id="坐标系" tabindex="-1">坐标系 <a class="header-anchor" href="#坐标系" aria-label="Permalink to &quot;坐标系&quot;">​</a></h2><ul><li>对外 API 统一使用<strong>度和米</strong>：纬度 / 经度 / heading / pitch / roll 为度，高度为米（WGS84 椭球海拔）。</li><li>经纬高元组输入顺序是 <code>[经度, 纬度, 高度]</code>（遵循 GeoJSON），与对象形式 <code>{ longitude, latitude, height }</code> 字段顺序相反，混用时易出错。</li><li>heading / pitch / roll 相对<strong>当地东北天（ENU）坐标系</strong>。</li></ul><h2 id="资源与生命周期" tabindex="-1">资源与生命周期 <a class="header-anchor" href="#资源与生命周期" aria-label="Permalink to &quot;资源与生命周期&quot;">​</a></h2><ul><li>Tellux 不托管 Three.js 场景以外的 DOM；销毁 <code>Viewer</code> 释放 WebGL 资源、控制器、纹理和事件监听器，但容器元素本身由调用方管理。</li><li>页面卸载（<code>beforeunload</code>）时浏览器的同步资源释放不可靠，销毁应优先放在组件卸载 / 路由切换时机，<code>beforeunload</code> 仅作兜底。</li></ul><h2 id="不在-tellux-能力范围内" tabindex="-1">不在 Tellux 能力范围内 <a class="header-anchor" href="#不在-tellux-能力范围内" aria-label="Permalink to &quot;不在 Tellux 能力范围内&quot;">​</a></h2><p>以下能力 Tellux 目前<strong>不提供</strong>，需要应用层自行实现或评估后续是否纳入：</p><ul><li>地形开挖、地形编辑、等高线生成等地形分析能力。</li><li>空间分析（缓冲区、叠加分析、可视域）。</li><li>时间轴动画、轨迹回放等业务级时间管理（<code>clock</code> 只驱动太阳方向）。</li><li>地理要素的属性表 UI、图层树 UI（<code>LayerManager</code> 只提供数据和状态，不提供界面）。</li></ul>',28)])])}const g=o(d,[["render",i]]);export{b as __pageData,g as default};
